let schedule_goal ~callback c g =
   (* actually schedule the goal, ie call the prover. This function returns
      immediately. *)
  let check = get_check_of_goal g in
  let s = c.Controller_itp.controller_session in
  let warn = Gnat_expl.is_warning_kind (Gnat_expl.get_check_kind check) in
  if Gnat_config.parallel > 1 then begin
    let provers =
      if warn then [Option.get (Gnat_config.prover_warn)] else Gnat_config.provers
    in
    let remaining = ref (List.length provers) in
    let callback pa pas =
      let prover =
        (Session_itp.get_proof_attempt_node s pa).Session_itp.prover.Whyconf.prover_name
      in
      if Gnat_config.logging then Logging.log g prover pas;
      if !remaining = 0 then ()
      else match pas with
        | Controller_itp.Done pr ->
          remaining := !remaining - 1;
          begin match pr.Call_provers.pr_answer with
          | Call_provers.Valid ->
            C.interrupt_proof_attempts_for_goal c g;
            remaining := 0;
            callback pa pas
          | _ ->
            if !remaining = 0 then callback pa pas else ()
          end
        | _ -> ()
    in
    List.iter (fun p -> schedule_goal_with_prover ~callback c g p) provers
  end else begin
    let p = if warn then Option.get (Gnat_config.prover_warn)
      else find_best_untried_prover c.Controller_itp.controller_session g in
    schedule_goal_with_prover ~callback c g p

let ending c () =
  Debug.Stats.record_timing "gnatwhy3.run_vcs"
    (fun () -> C.remove_all_valid_ce_attempt c.Controller_itp.controller_session);
  Debug.Stats.record_timing "gnatwhy3.save_session" (fun () -> C.save_session c);
  Gnat_checks.iter (report_messages c);
  let s = Buffer.contents escape_buffer in
  if s <> "" then
    Gnat_report.add_warning s;
  Gnat_report.print_messages ();
  (* Dump profiling data (when compiled with profiling enabled) to file whose
     name is based on the processed .mlw file; otherwise profile data from
     several compilation would be written to a single gmon.out file and
     overwrite each other. When compiled with profiling disabled it has no
     visible effect. Note: we set the filename just before the program exit
     to not interfere with profiling of provers.
   *)
  let basename =
    Filename.chop_extension
      (Filename.basename Gnat_config.filename) in
  Unix.putenv "GMON_OUT_PREFIX" (basename ^ "_gnatwhy3_gmon.out")

